using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Racing;
using HarborValeGreybox.Launch;
namespace HarborValeGreybox.Workshop {
public class TurboAudioPlayerProbe:MonoBehaviour {
 static string folder;readonly List<string> lines=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--turbo-audio-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<a.Length?Path.GetFullPath(a[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=Path.Combine(folder,"isolated-v5.json");}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var g=new GameObject("Turbo audio native verification");DontDestroyOnLoad(g);g.AddComponent<TurboAudioPlayerProbe>();}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}
 void Log(string message,string stack,LogType kind){if(!failed&&(kind==LogType.Error||kind==LogType.Exception)){failed=true;lines.Add("FAIL runtime: "+message);Write();Application.Quit(1);}}
 void Write()=>File.WriteAllLines(Path.Combine(folder,"results.txt"),lines);
 void Check(bool good,string message){lines.Add((good?"PASS ":"FAIL ")+message);if(!good){failed=true;Write();Application.Quit(1);throw new Exception(message);}}
 void Update(){if(!failed&&deadline>0&&Time.realtimeSinceStartupAsDouble>deadline)Check(false,"Native turbo audio timeout");}
 IEnumerator Wait(Func<bool> condition){while(!condition())yield return null;yield return new WaitForSecondsRealtime(.6f);}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return new WaitForSecondsRealtime(.3f);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 IEnumerator Pull(ExpandedWorkshop shop,TurboReleaseMode mode,Vector3 position,Quaternion rotation){var car=shop.Car;car.ResetAt(position,rotation);car.externalInput=true;car.commandedHandbrake=false;yield return new WaitForSecondsRealtime(.6f);Check(shop.Open(),"Stopped workshop opens for "+mode);string paid=File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests);Check(shop.ChooseTurboRelease(mode),"Select "+mode+" in real workshop");Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==paid,"Audio selection leaves paid ledger byte-unchanged "+mode);shop.View.ShowTurboAudio();yield return Capture("Turbo_Audio_"+mode);shop.Close();var effects=car.GetComponent<WorkshopEffects>();var tap=Camera.main.gameObject.AddComponent<TurboNativeAudioTap>();tap.Begin();car.commandedPedal=1;car.commandedServiceBrake=1;yield return new WaitForSecondsRealtime(2.5f);car.commandedServiceBrake=0;yield return new WaitForSecondsRealtime(2.3f);int before=effects.ReleaseCount;Check(car.Engine.BoostBar>.08f,"Actual turbo pull builds pressure for "+mode);car.commandedPedal=0;yield return new WaitForSecondsRealtime(.2f);Check(effects.ReleaseCount==before+1&&effects.LastReleasePressure>.08f,"Real boost plus driver lift fires "+mode);yield return new WaitForSecondsRealtime(1);Check(effects.ReleaseCount==before+1,"Held lift does not repeat "+mode);var data=tap.Finish(Path.Combine(folder,"Native_"+mode+".wav"));Check(data>10000,"Native listener captures audible "+mode);Destroy(tap);car.commandedPedal=0;car.commandedServiceBrake=1;}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+180;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);var shop=FindAnyObjectByType<ExpandedWorkshop>();var trial=FindAnyObjectByType<DocksideTrialDirector>();for(int i=0;i<30;i++)trial.Store.Settle(Finish(trial.Definition),out _);Check(shop.Open(),"Workshop opens on isolated paid profile");Check(shop.TurboRelease==TurboReleaseMode.BlowOffValve,"Default release is blow-off valve");shop.View.ShowTurboAudio();shop.PreviewTurboRelease(TurboReleaseMode.BlowOffValve);yield return new WaitForSecondsRealtime(.25f);Check(shop.Car.GetComponentsInChildren<AudioSource>().Any(a=>a.clip!=null&&a.clip.name=="Turbo audition BlowOffValve"&&a.isPlaying),"Garage audition plays through a real AudioSource");Check(shop.Car.Engine.BoostBar==0,"Audition cannot create real boost on stock NA car");shop.StopTurboPreview();Check(!shop.Car.GetComponentsInChildren<AudioSource>().Any(a=>a.clip!=null&&a.clip.name.StartsWith("Turbo audition")&&a.isPlaying),"Garage audition stops cleanly");foreach(var o in shop.Catalog.MissingPath(shop.Build,shop.Catalog.Find("induction_small_1")))Check(shop.Install(o.id),"Install actual turbo path "+o.id);foreach(var o in shop.Catalog.MissingPath(shop.Build,shop.Catalog.Find("tires_3")))Check(shop.Install(o.id),"Install actual grip path "+o.id);string definition=JsonUtility.ToJson(shop.Car.Engine.definition);shop.Close();Vector3 position=shop.Car.Body.position;Quaternion rotation=shop.Car.Body.rotation;yield return Pull(shop,TurboReleaseMode.BlowOffValve,position,rotation);yield return Pull(shop,TurboReleaseMode.Flutter,position,rotation);Check(JsonUtility.ToJson(shop.Car.Engine.definition)==definition,"Sound choices cannot change torque curves, mass or transmission");shop.Car.ResetAt(position,rotation);shop.Car.externalInput=false;string paid=File.ReadAllText(trial.Store.PathName);string preference=File.ReadAllText(trial.Store.PathName+".turbo-audio.json");HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);shop=FindAnyObjectByType<ExpandedWorkshop>();Check(shop.IsTest&&shop.TurboRelease==TurboReleaseMode.BlowOffValve,"Apex visit has independent default audio preference");Check(shop.Open()&&shop.ChooseTurboRelease(TurboReleaseMode.Flutter),"Apex audio selection is free and temporary");Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==paid&&File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests+".turbo-audio.json")==preference,"Apex cannot change paid ledger or Finch preference");shop.Close();HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);shop=FindAnyObjectByType<ExpandedWorkshop>();Check(shop.TurboRelease==TurboReleaseMode.Flutter,"Finch flutter preference reloads after scene roundtrip");Check(shop.Car.GetComponentsInChildren<WheelCollider>().Length==4,"Audio adds no wheel physics");Check(!failed,"No native runtime errors");Write();Application.Quit(0);}
}
public sealed class TurboNativeAudioTap:MonoBehaviour {
 readonly object sync=new object();readonly List<float> samples=new List<float>();bool recording;int channels,rate;
 public void Begin(){rate=AudioSettings.outputSampleRate;lock(sync){samples.Clear();recording=true;}}
 void OnAudioFilterRead(float[] data,int channelCount){lock(sync){if(recording){channels=channelCount;samples.AddRange(data);}}}
 public int Finish(string file){float[] values;lock(sync){recording=false;values=samples.ToArray();}using(var w=new BinaryWriter(File.Create(file))){int ch=Math.Max(1,channels);w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+values.Length*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)ch);w.Write(rate);w.Write(rate*ch*2);w.Write((short)(ch*2));w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(values.Length*2);foreach(var v in values)w.Write((short)(Math.Max(-1,Math.Min(1,v))*32767));}float peak=values.Length==0?0:values.Max(v=>Math.Abs(v));File.WriteAllText(file+".txt","Actual native listener samples="+values.Length+" rate="+rate+" channels="+channels+" peak="+peak);return peak>.01?values.Length:0;}
}
}
